div.script:
function gmDelReel(btn) {
    var body = document.getElementById('gm_reel_body');
    var row = btn.closest('tr');
    if (body.rows.length > 1) {
        row.remove();
    } else {
        row.querySelectorAll('input').forEach(function (i) {
            if (i.type !== 'hidden') { i.value = ''; }
        });
    }
}
function gmAddReel() {
    var body = document.getElementById('gm_reel_body');
    var row = body.rows[0].cloneNode(true);
    row.querySelectorAll('input').forEach(function (i) {
        if (i.name === 'reel_garder') { i.value = '0'; }
        else { i.value = ''; }
    });
    row.querySelectorAll('select').forEach(function (s) { s.value = ''; });
    row.querySelectorAll('small').forEach(function (s) { s.remove(); });
    body.appendChild(row);
}

form.script:
// Sans widget Odoo sur le portail : on montre
// ou on cache le bloc à la main.
(function () {
    var choix = document.getElementById('gm_transport');
    var bloc = document.getElementById('gm_immat_bloc');
    if (!choix || !bloc) { return; }
    choix.addEventListener('change', function () {
        var service = choix.value === 'service';
        bloc.style.display = service ? '' : 'none';
        if (!service) {
            var champ = document.getElementById('gm_immat');
            if (champ) { champ.value = ''; }
        }
    });
})();

div.script:
function gmDelFrais(btn) {
    var body = document.getElementById('gm_frais_body');
    var row = btn.closest('tr');
    if (body.rows.length > 1) {
        row.remove();
    } else {
        row.querySelectorAll('input').forEach(function (i) { i.value = ''; });
        row.querySelectorAll('select').forEach(function (s) { s.value = ''; });
    }
}
function gmAddFrais() {
    var body = document.getElementById('gm_frais_body');
    var row = body.rows[0].cloneNode(true);
    row.querySelectorAll('input').forEach(function (i) { i.value = ''; });
    row.querySelectorAll('select').forEach(function (s) { s.value = ''; s.dataset.selected = ''; });
    body.appendChild(row);
}

/* --- membres (mode équipe) : liste déroulante + synchro
       des sélecteurs « Missionnaire » des frais --- */
function gmGetMembres() {
    var out = [];
    var chef = document.getElementById('gm_employee');
    if (chef && chef.value) {
        out.push({id: chef.value,
                  name: chef.options[chef.selectedIndex].text.trim() + ' (chef)'});
    }
    document.querySelectorAll('#gm_membre_list li').forEach(function (li) {
        out.push({id: li.getAttribute('data-emp'),
                  name: li.querySelector('span').textContent.trim()});
    });
    return out;
}
function gmRefreshFraisMembres() {
    if (!document.getElementById('gm_membre_list')) { return; }
    var membres = gmGetMembres();
    document.querySelectorAll('select[name="frais_membre"]').forEach(function (sel) {
        var cur = sel.value || sel.dataset.selected || '';
        sel.innerHTML = '';
        var def = document.createElement('option');
        def.value = '';
        def.textContent = 'Chef de mission';
        sel.appendChild(def);
        membres.forEach(function (m) {
            var o = document.createElement('option');
            o.value = m.id;
            o.textContent = m.name;
            if (m.id === cur) { o.selected = true; }
            sel.appendChild(o);
        });
    });
}
function gmAddMembre() {
    var sel = document.getElementById('gm_membre_pick');
    var chef = document.getElementById('gm_employee');
    if (!sel || !sel.value) { return; }
    if (chef && chef.value === sel.value) { sel.value = ''; return; }
    if (document.querySelector('#gm_membre_list li[data-emp="' + sel.value + '"]')) {
        sel.value = '';
        return;
    }
    var li = document.createElement('li');
    li.className = 'list-group-item d-flex justify-content-between align-items-center';
    li.setAttribute('data-emp', sel.value);
    var span = document.createElement('span');
    span.textContent = sel.options[sel.selectedIndex].text.trim();
    var hidden = document.createElement('input');
    hidden.type = 'hidden';
    hidden.name = 'membre_ids';
    hidden.value = sel.value;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn btn-sm btn-outline-danger';
    btn.innerHTML = '&times;';
    btn.title = 'Retirer ce membre';
    btn.onclick = function () { gmDelMembre(btn); };
    li.appendChild(span);
    li.appendChild(hidden);
    li.appendChild(btn);
    document.getElementById('gm_membre_list').appendChild(li);
    sel.value = '';
    gmRefreshFraisMembres();
}
function gmDelMembre(btn) {
    btn.closest('li').remove();
    gmRefreshFraisMembres();
}
(function () {
    var chef = document.getElementById('gm_employee');
    if (chef) { chef.addEventListener('change', gmRefreshFraisMembres); }
    gmRefreshFraisMembres();
})();
